import syncBus from '../utils/syncBus';

class SubscriptionService {
  constructor() {
    this.listeners = new Set();
    this._init();
    this._initSyncBus();
  }

  _init() {
    try {
      // Purge legacy local storage keys if they exist
      const legacyKey = 'dealflow_subscriptions';
      if (localStorage.getItem(legacyKey)) {
        localStorage.removeItem(legacyKey);
      }
      
      const saved = localStorage.getItem(STORAGE_KEY);
      if (!saved) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_SUBS));
      }
    } catch (e) {
      console.error('Failed to initialize subscriptionService', e);
    }
  }

  _initSyncBus() {
    syncBus.subscribe('subscriptions', (payload) => {
      try {
        if (payload?.subscriptions && Array.isArray(payload.subscriptions)) {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(payload.subscriptions));
        }
      } catch (err) {
        console.error('[Customer SubscriptionService] Error handling sync event:', err);
      }
      this._notify();
    });
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }


  _notify() {
    this.listeners.forEach((l) => l());
  }

  getAllSubscriptions() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch {
      return [];
    }
  }

  getSubscriptionById(id) {
    return this.getAllSubscriptions().find((s) => s.id === id);
  }

  createSubscriptionFromQuote(quote) {
    // Only process if there are recurring items
    const recurringLines = (quote.items || []).filter(
      item => item.product?.category === 'Subscriptions' || item.product?.category === 'Maintenance'
    );
    
    if (recurringLines.length === 0) return null;

    const subs = this.getAllSubscriptions();
    
    // Check if contract already exists
    if (subs.some(s => s.quoteId === quote.id)) {
      return null;
    }

    const newContract = {
      id: 'SUB-' + Math.random().toString(36).substring(2, 8).toUpperCase(),
      quoteId: quote.id,
      customer: quote.customer_name || quote.company_name || quote.cust || 'Unknown Customer',
      oneTimeItems: (quote.items || []).filter(
        item => item.product?.category !== 'Subscriptions' && item.product?.category !== 'Maintenance'
      ).map(item => ({
        name: item.product?.name || 'Item',
        qty: item.qty || 1,
        price: item.product?.price || 0
      })),
      recurringItems: recurringLines.map((item, idx) => ({
        id: 'item-' + idx + '-' + Math.random().toString(36).substring(2, 6),
        name: item.product?.name || 'Recurring Item',
        interval: 'monthly',
        qty: item.qty || 1,
        unitPrice: (item.product?.price || 0) * (1 - ((item.discount || 0) / 100)),
        status: 'ACTIVE'
      })),
      billingCycleDay: new Date().getDate(),
      status: 'ACTIVE',
      createdAt: new Date().toISOString()
    };

    subs.push(newContract);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(subs));
    this._notify();
    syncBus.publish('subscriptions', { subscriptions: subs, contract: newContract, action: 'create' });
    return newContract;
  }

  updateSubscriptionQty(contractId, itemId, newQty) {
    const subs = this.getAllSubscriptions();
    const contract = subs.find(c => c.id === contractId);
    if (!contract) return null;

    contract.recurringItems = contract.recurringItems.map(item => {
      if (item.id === itemId) {
        return { ...item, qty: newQty };
      }
      return item;
    });

    localStorage.setItem(STORAGE_KEY, JSON.stringify(subs));
    this._notify();
    syncBus.publish('subscriptions', { subscriptions: subs, contract, action: 'update_qty' });
    return contract;
  }

  cancelSubscriptionLine(contractId, itemId) {
    const subs = this.getAllSubscriptions();
    const contract = subs.find(c => c.id === contractId);
    if (!contract) return null;

    contract.recurringItems = contract.recurringItems.map(item => {
      if (item.id === itemId) {
        return { ...item, status: 'CANCELLED' };
      }
      return item;
    });
    
    localStorage.setItem(STORAGE_KEY, JSON.stringify(subs));
    this._notify();
    syncBus.publish('subscriptions', { subscriptions: subs, contract, action: 'cancel_line' });
    return contract;
  }
}

export default new SubscriptionService();
